const raw = $json.content?.[0]?.text ?? $json.text ?? $json.output ?? JSON.stringify($json);
let card = {};
try { card = JSON.parse(String(raw).match(/\{[\s\S]*\}/)[0]); } catch (e) { card = { is_insurance_card: false, description: 'an image Noor could not read' }; }
const patient = $('Lookup Patient').first().json || {};
const lang = String(patient.language || '').startsWith('ar') ? 'ar' : 'en';
const firstName = String(patient.name || $('Message Info').first().json.profile_name || '').split(' ')[0];
const today = DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd');
const expiry = /^\d{4}-\d{2}-\d{2}$/.test(String(card.expiry || '')) ? card.expiry : '';
const expired = !!expiry && expiry < today;
const id = String(card.member_id || '');
const last4 = id.length > 4 ? id.slice(-4) : id;
const insurer = String(card.insurer || 'insurance');
let reply;
if (lang === 'ar') {
  reply = expired
    ? 'شكراً ' + firstName + '! قرأت بطاقة ' + insurer + '، لكن يبدو أنها انتهت بتاريخ ' + expiry + '. يرجى إرسال بطاقة سارية، أو سيساعدك فريقنا.'
    : 'شكراً ' + firstName + '! استلمنا بطاقة تأمين ' + insurer + (last4 ? ' (رقم العضوية ينتهي بـ ' + last4 + ')' : '') + '. سيتأكد فريقنا من التغطية قبل موعدك.';
} else {
  reply = expired
    ? 'Thanks ' + firstName + '! I read your ' + insurer + ' card, but it looks like it expired on ' + expiry + '. Please send a valid card, or our team will help you.'
    : 'Thanks ' + firstName + '! We received your ' + insurer + ' card' + (last4 ? ' (member ID ending ' + last4 + ')' : '') + '. Our team will confirm your coverage before your visit.';
}
return { json: {
  is_card: card.is_insurance_card === true,
  insurer: String(card.insurer || ''), plan: String(card.plan || ''), member_name: String(card.member_name || ''),
  member_id: id, expiry, expired, description: String(card.description || ''),
  reply,
  staff_alert: '[Noor] Insurance card from +' + $('Message Info').first().json.phone + ': ' + insurer + ' ' + String(card.plan || '') + ', member ' + (card.member_name || '?') + ', ID ' + (id || '?') + ', expiry ' + (expiry || '?') + (expired ? ' - EXPIRED' : '') + '. Please verify coverage.'
} };

// Switches (from the Noor Settings tab, synced to a data table) and whether staff paused this chat.
const on = {};
$('Get Settings').all().forEach(function (i) { const r = i.json || {}; const k = String(r.feature || '').trim(); if (k) on[k] = String(r.enabled).trim().toUpperCase() === 'TRUE'; });
const last = ($('Get Takeover').all()[0] || {}).json || {};
const chatPaused = !!on.staff_takeover && String(last.paused || '').trim().toUpperCase() === 'TRUE';
return [{ json: Object.assign({}, on, { typing_indicator: !!on.typing_indicator && !chatPaused, chat_paused: chatPaused }) }];

// Staff takeover (switch: staff_takeover). Owner commands: #pause <phone>, #resume <phone>, #reply <phone> <message>.
const info = $('Message Info').first().json;
const m = String(info.text || '').trim().match(/^#\s*(pause|resume|reply)\s+\+?(\d{8,15})\b\s*([\s\S]*)$/i);
const now = DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm');
if (!m) return [{ json: { time: now, phone: '', paused: '', action: 'invalid', by: 'owner', message: '', owner_text: 'Use #pause 9715XXXXXXXX, #reply 9715XXXXXXXX your message, or #resume 9715XXXXXXXX.' } }];
const cmd = m[1].toLowerCase();
const target = m[2];
const msg = String(m[3] || '').trim();
let ownerText = '';
if (cmd === 'pause') ownerText = 'Noor is paused for +' + target + '. Their new messages will be forwarded to you here. Answer with #reply ' + target + ' your message, and hand back with #resume ' + target + '.';
if (cmd === 'resume') ownerText = 'Noor is back on for +' + target + '.';
if (cmd === 'reply' && msg) ownerText = 'Sent to +' + target + ': "' + msg.slice(0, 200) + '". Noor stays paused for this patient until you send #resume ' + target + '.';
if (cmd === 'reply' && !msg) ownerText = 'Noor is paused for +' + target + ', but no message was sent. Write it after the number, e.g. #reply ' + target + ' Hello, this is Dr Sara from BrightSmile.';
return [{ json: { time: now, phone: target, paused: cmd === 'resume' ? 'FALSE' : 'TRUE', action: cmd, by: 'owner', message: cmd === 'reply' ? msg : '', owner_text: ownerText } }];

