// Picks the spoken script and the ElevenLabs voice for the language (voices come from the setup sheet).
const reply = String($('Ask Noor').first().json.reply || '');
const j = $input.first().json || {};
let script = '';
try { script = String((j.content && j.content[0] && j.content[0].text) || j.text || j.output || j.message || ''); } catch (e) { script = ''; }
if (!script.trim() || script.length > 900) script = reply;
script = script.replace(/\[[^\]]*\]/g, '').replace(/[*_~#>`]/g, '').replace(/\p{Extended_Pictographic}️?/gu, '').replace(/https?:\/\/\S+/g, '').replace(/…/g, '...').replace(/\s+/g, ' ').trim().slice(0, 700);
const setup = {};
try { $('Get Setup').all().forEach(function (i) { const r = i.json || {}; if (r.name) setup[String(r.name).trim()] = String(r.value || '').trim(); }); } catch (e) { /* defaults */ }
const arabic = /[؀-ۿ]/.test(reply);
const voice_id = arabic ? (setup.arabic_voice_id || 'qvaae5vgWkophsefWOzT') : (setup.english_voice_id || 'rttOA5OKNtzdQVZRYl7c');
// eleven_v3 "natural" setting for both languages: human pauses, no overacting
return [{ json: { script: script, script_el: script, english: !arabic, voice_id: voice_id, model_id: 'eleven_v3', voice_settings: { stability: 0.5, similarity_boost: 0.8 }, use_elevenlabs: true } }];

// ElevenLabs sends Ogg/Opus; label it so WhatsApp shows it as a voice note.
const out = [];
for (const item of $input.all()) {
  if (item.binary && item.binary.data) {
    item.binary.data.mimeType = 'audio/ogg';
    item.binary.data.fileName = 'noor.ogg';
    item.binary.data.fileExtension = 'ogg';
  }
  out.push(item);
}
return out;

// Several quick messages from the same patient are answered together. Only the run for the newest message continues.
const me = $('Message Info').first().json;
const myId = String($('Only Patient Messages').first().json.messages[0].id || '');
let rows = [];
try { rows = $('Get Recent Messages').all().map(function (i) { return i.json || {}; }).filter(function (r) { return String(r.phone) === String(me.phone) && r.msg_id; }); } catch (e) { rows = []; }
rows.sort(function (a, b) { return Number(a.at_ms) - Number(b.at_ms); });
const now = Date.now();
const recent = rows.filter(function (r) { return now - Number(r.at_ms) <= 120000; });
const mine = recent.some(function (r) { return String(r.msg_id) === myId; });
if (!recent.length || !mine) return [{ json: { combined: String(me.text || ''), count: 1, latest_ms: now } }];
const latest = recent[recent.length - 1];
if (String(latest.msg_id) !== myId) return []; // a newer message will answer all of them
const texts = recent.map(function (r) { return String(r.text || '').trim(); }).filter(Boolean);
return [{ json: { combined: texts.length > 1 ? texts.join('\n') : String(me.text || ''), count: Math.max(1, texts.length), latest_ms: Number(latest.at_ms) } }];

// Offered appointment times become tap-to-choose buttons (2-3 times) or a list (4-9 times). Switch: time_buttons.
const reply = String($('Ask Noor').first().json.reply || '');
let on = false;
try { $('Get Settings').all().forEach(function (i) { const r = i.json || {}; if (String(r.feature || '').trim() === 'time_buttons') on = String(r.enabled).trim().toUpperCase() === 'TRUE'; }); } catch (e) { on = false; }
const none = [{ json: { has_choices: false } }];
if (!on || !reply || reply.length > 1000) return none;
const ar = /[؀-ۿ]/.test(reply);
const timeG = /(\d{1,2}[:.]\d{2}(?:\s*[ap]\.?m\.?)?|\b\d{1,2}\s*[ap]\.?m\.?|[٠-٩]{1,2}[:.][٠-٩]{2})(?:\s*(?:صباحاً|صباحا|مساءً|مساء|ظهراً|عصراً|ص|م)(?![؀-ۿ]))?/gi;
const dayRe = /(monday|tuesday|wednesday|thursday|friday|saturday|sunday|today|tomorrow|الاثنين|الإثنين|الثلاثاء|الأربعاء|الاربعاء|الخميس|الجمعة|السبت|الأحد|الاحد|اليوم|بكرة|بكره|غداً|غدا)/i;
const bullet = /^\s*(?:[-•*·▪◦–]|\d{1,2}[.)]|[٠-٩]{1,2}[.)])\s*/;
let day = '';
let bad = false;
const opts = [];
reply.split('\n').forEach(function (line) {
  const t = line.trim();
  if (!t) return;
  const times = t.match(timeG) || [];
  const dm = t.match(dayRe);
  if (!bullet.test(t)) { if (dm && !times.length) day = dm[0]; return; }
  if (!times.length) return;
  if (times.length > 1 && /,|،|\bor\b|أو/.test(t)) { bad = true; return; }
  const clean = t.replace(bullet, '').replace(/[*_~]/g, '').trim();
  opts.push({ clean: clean, time: times[0].trim(), day: dm ? dm[0] : day });
});
if (bad || opts.length < 2 || opts.length > 9) return none;
const days = Array.from(new Set(opts.map(function (o) { return String(o.day || '').toLowerCase(); })));
const short = function (d) { if (!d) return ''; return /^[a-z]/i.test(d) ? d.charAt(0).toUpperCase() + d.slice(1, 3).toLowerCase() : d; };
const seen = {};
const choices = [];
opts.forEach(function (o) {
  const title = ((days.length > 1 && o.day ? short(o.day) + ' ' : '') + o.time.replace(/\s+/g, ' ')).slice(0, 20);
  if (seen[title]) return;
  seen[title] = 1;
  const full = (o.day && !dayRe.test(o.clean) ? o.day + ' ' : '') + o.clean;
  choices.push({ id: ('opt:' + full).slice(0, 200), title: title, description: full.slice(0, 72) });
});
if (choices.length < 2) return none;
const other = { id: 'opt:other', title: ar ? 'موعد آخر' : 'Another time' };
let interactive;
if (choices.length <= 3) {
  const btns = choices.map(function (c) { return { type: 'reply', reply: { id: c.id, title: c.title } }; });
  if (btns.length < 3) btns.push({ type: 'reply', reply: other });
  interactive = { type: 'button', body: { text: reply }, action: { buttons: btns } };
} else {
  const rows = choices.map(function (c) { return { id: c.id, title: c.title.slice(0, 24), description: c.description }; });
  rows.push({ id: other.id, title: other.title });
  interactive = { type: 'list', body: { text: reply }, action: { button: ar ? 'اختر الموعد' : 'Choose a time', sections: [{ title: ar ? 'المواعيد المتاحة' : 'Available times', rows: rows }] } };
}
return [{ json: { has_choices: true, interactive: interactive, count: choices.length } }];

// Lead source: where did this patient come from? Saves one row for each new patient, and for every tap on a Click-to-WhatsApp ad.
const flags = (function () { try { return $('Feature Flags').first().json || {}; } catch (e) { return {}; } })();
if (flags.source_tracking === false) return [];
const info = $('Message Info').first().json || {};
if (info.is_owner_command || String(info.phone) === String(info.owner_phone) || /^000000000000/.test(String(info.phone))) return [];
const m = (($('Only Patient Messages').first().json || {}).messages || [])[0] || {};
const p = $('Lookup Patient').first().json || {};
const isNew = !String(p.phone || '').replace(/\D/g, '');
const ref = m.referral || null;
const text = String(info.text || '');
const low = text.toLowerCase();
let source = '', detail = '', adId = '';
if (ref) {
  source = ref.source_type === 'post' ? 'facebook_instagram_post' : 'meta_ad';
  detail = String(ref.headline || ref.body || ref.source_url || '').slice(0, 200);
  adId = String(ref.source_id || '');
} else {
  const tag = (text.match(/\[(ig|instagram|fb|facebook|tt|tiktok|google|maps|gmb|web|site|website|qr|snap|snapchat|ref:[\w-]+)\]/i) || [])[1];
  const map = { ig: 'instagram', instagram: 'instagram', fb: 'facebook', facebook: 'facebook', tt: 'tiktok', tiktok: 'tiktok', google: 'google', maps: 'google', gmb: 'google', web: 'website', site: 'website', website: 'website', qr: 'qr_code', snap: 'snapchat', snapchat: 'snapchat' };
  if (tag) { source = map[tag.toLowerCase()] || tag.toLowerCase().replace('ref:', ''); detail = 'link tag'; }
  else if (isNew) {
    const words = [['instagram', 'instagram'], ['insta', 'instagram'], ['انستا', 'instagram'], ['tiktok', 'tiktok'], ['تيك توك', 'tiktok'], ['facebook', 'facebook'], ['فيسبوك', 'facebook'], ['فيس بوك', 'facebook'], ['snapchat', 'snapchat'], ['سناب', 'snapchat'], ['google', 'google'], ['جوجل', 'google'], ['قوقل', 'google'], ['website', 'website'], ['موقع', 'website'], ['friend', 'referral'], ['صديق', 'referral'], ['recommend', 'referral']];
    const hit = words.find(function (w) { return low.indexOf(w[0]) >= 0; });
    source = hit ? hit[1] : 'direct_whatsapp';
    detail = hit ? 'first message mentions ' + hit[0] : '';
  }
}
if (!source) return [];
return [{ json: { phone: String(info.phone), name: String(p.name || info.profile_name || ''), source: source, detail: detail, ad_id: adId, is_new: isNew ? 'TRUE' : 'FALSE', first_message: text.slice(0, 300), time: DateTime.now().setZone('Asia/Dubai').toFormat('yyyy-MM-dd HH:mm') } }];

